test-warm.shaders/composite.fsh:
#version 120
#include "/lib/settings.glsl"

uniform sampler2D colortex0;
uniform float viewWidth;
uniform float viewHeight;
uniform float frameTimeCounter;

varying vec2 texcoord;

/* DRAWBUFFERS:0 */
void main() {
    vec3 color = texture2D(colortex0, texcoord).rgb;
    // warm grade + exposure, a slow breathing pulse to prove the uniform bridge
    color *= EXPOSURE;
    color.r *= 1.0 + 0.12 * WARMTH;
    color.b *= max(0.0, 1.0 - 0.15 * WARMTH);
    color *= 0.97 + 0.03 * sin(frameTimeCounter * 1.5);
    float aspect = viewWidth / max(viewHeight, 1.0);
    color /= 1.0 + 0.0 * aspect;
    #if GRAYSCALE == 1
        float l = dot(color, vec3(0.299, 0.587, 0.114));
        color = vec3(l);
    #endif
    gl_FragColor = vec4(color, 1.0);
}

test-warm.shaders/final.fsh:
#version 120
uniform sampler2D colortex0;
varying vec2 texcoord;
void main() {
    vec3 color = texture2D(colortex0, texcoord).rgb;
    // the classic BSL-style vignette + a soft contrast S-curve
    float d = distance(texcoord, vec2(0.5));
    color *= 1.0 - 0.25 * smoothstep(0.35, 0.75, d);
    color = clamp((color - 0.5) * 1.06 + 0.5, 0.0, 1.5);
    gl_FragColor = vec4(color, 1.0);
}
